using System;
using System.Text.Json;
using Azure;
// Test deserialization only 
var json = """{"code":"TestCode","message":"TestMessage"}""";
var deserialized = JsonSerializer.Deserialize<ResponseError>(json);
Console.WriteLine($"Deserialized: Code={deserialized?.Code}, Message={deserialized?.Message}");

// Test Utf8JsonWriter serialization via IJsonModel-like pattern
// Check if it implements any write interface
var writer = new Utf8JsonWriter(Console.OpenStandardOutput());
try {
    JsonSerializer.Serialize(writer, deserialized);
} catch (Exception e) {
    Console.Error.WriteLine($"\nSerialize throws: {e.GetType().Name}: {e.Message}");
}
EOF
